<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Http\Requests\StoreJenisServisRequest;use App\Http\Requests\UpdateJenisServisRequest;use App\Models\JenisServis;use App\Services\MasterAuditService;use Illuminate\Http\RedirectResponse;use Illuminate\View\View;
class JenisServisController extends Controller { public function index():View{return view('admin.jenis-servis.index',['items'=>JenisServis::when(request('q'),fn($q,$v)=>$q->where('nama_servis','like','%'.$v.'%')->orWhere('deskripsi','like','%'.$v.'%'))->orderBy('nama_servis')->paginate(10)->withQueryString()]);} public function create():View{return view('admin.jenis-servis.create',['item'=>new JenisServis(['status'=>'aktif','estimasi_harga'=>0])]);} public function store(StoreJenisServisRequest $r,MasterAuditService $a):RedirectResponse{$i=JenisServis::create($r->validated());$a->record('create','jenis_servis',$i->id_jenis_servis,'Menambah jenis servis');return redirect()->route('admin.jenis-servis.index')->with('success','Jenis servis tersimpan.');} public function show(JenisServis $jenisServis):View{return view('admin.jenis-servis.show',['item'=>$jenisServis]);} public function edit(JenisServis $jenisServis):View{return view('admin.jenis-servis.edit',['item'=>$jenisServis]);} public function update(UpdateJenisServisRequest $r,JenisServis $jenisServis,MasterAuditService $a):RedirectResponse{$jenisServis->update($r->validated());$a->record('update','jenis_servis',$jenisServis->id_jenis_servis,'Mengubah jenis servis');return redirect()->route('admin.jenis-servis.show',$jenisServis)->with('success','Jenis servis diperbarui.');} public function toggle(JenisServis $jenisServis,MasterAuditService $a):RedirectResponse{$x=$jenisServis->status==='aktif'?'nonaktif':'aktif';$jenisServis->update(['status'=>$x]);$a->record('status','jenis_servis',$jenisServis->id_jenis_servis,'Status menjadi '.$x);return back();} }
